const items = $input.all();
const now = new Date();
const expired = [];

for (const item of items) {
  const row = item.json;
  const rowNum = row['row_number'];
  // Column header is 'Дедлайн' (deadline date)
  const deadline = row['Дедлайн'] || row['F'];
  if (rowNum && deadline && new Date(deadline) < now) {
    expired.push({ json: { row_number: rowNum } });
  }
}

// Sort descending: delete from bottom to top so indices don't shift
expired.sort((a, b) => b.json.row_number - a.json.row_number);

return expired;

const niches = $input.all();
const ktruSet = new Set();
const regionSet = new Set();
const validPairs = new Set();

for (const n of niches) {
  ktruSet.add(n.json.ktru_code);
  regionSet.add(parseInt(n.json.region_code));
  validPairs.add(`${n.json.region_code}:${n.json.ktru_code}`);
}

const ktruList = [...ktruSet];
const regionQuery = [...regionSet].map(r => `region=${r}`).join('&');

const batches = [];
for (let i = 0; i < ktruList.length; i += 5) {
  const classifier = ktruList.slice(i, i + 5);
  const classifierQuery = classifier.map(c => `classifier=${encodeURIComponent(c)}`).join('&');
  const url = `https://v2test.gosplan.info/fz44/purchases?max_price_ge=10000&max_price_le=200000&sort=published_at_desc&limit=100&stage=1&${regionQuery}&${classifierQuery}`;
  batches.push({
    json: {
      url,
      classifier,
      validPairs: [...validPairs]
    }
  });
}

const fallbackClassifierQuery = ktruList.slice(0,5).map(c => `classifier=${encodeURIComponent(c)}`).join('&');
const fallbackUrl = `https://v2test.gosplan.info/fz44/purchases?max_price_ge=10000&max_price_le=200000&sort=published_at_desc&limit=100&stage=1&${regionQuery}&${fallbackClassifierQuery}`;
return batches.length > 0 ? batches : [{ json: { url: fallbackUrl, classifier: [], validPairs: [] } }];

// n8n HTTP node splits JSON array into separate items — use $input.all()
const purchases = $input.all().map(item => item.json);
const batch = $('SiB: Main').first().json;
const classifier = batch.classifier || [];

// Валидные пары регион:КТРУ и просто регионы
const validPairs = new Set(batch.validPairs || []);
const validRegions = new Set((batch.validPairs || []).map(vp => parseInt(vp.split(':')[0])));

const safe = (s) => (s || '').toString().replace(/'/g, "''");

const rows = [];
for (const p of purchases) {
  if (!p.purchase_number) continue;
  if (!p.max_price || p.max_price < 10000 || p.max_price > 200000) continue;
  if (!p.collecting_finished_at) continue;

  const region = parseInt(p.region) || 0;
  const hasKtru = p.ktru && p.ktru.length > 0;
  const ktruCodes = hasKtru ? p.ktru : classifier;

  // Если КТРУ есть — проверяем точную пару регион:КТРУ
  // Если КТРУ пустой — доверяем API-фильтру, проверяем только регион
  const matched = hasKtru
    ? ktruCodes.some(k => validPairs.has(`${region}:${k}`))
    : validRegions.has(region);
  if (!matched) continue;

  const ktruArr = ktruCodes.length > 0
    ? 'ARRAY[' + ktruCodes.map(k => `'${safe(k)}'`).join(',') + ']'
    : 'ARRAY[]::text[]';
  const customerInn = (p.customers && p.customers[0]) ? `'${safe(p.customers[0])}'` : 'NULL';
  rows.push(`('${safe(p.purchase_number)}', ${region}, ${ktruArr}, ${parseFloat(p.max_price)}, '${safe(p.object_info || '')}', '${p.collecting_finished_at}'::timestamptz, ${customerInn})`);
}

const sql = rows.length > 0
  ? `INSERT INTO active_purchases (purchase_number, region_code, ktru_codes, max_price, subject, collecting_end, customer_inn) VALUES ${rows.join(', ')} ON CONFLICT (purchase_number) DO NOTHING;`
  : 'SELECT 1';

return [{ json: { sql } }];

const items = $input.all();
if (items.length === 0) return [];

const tenders = items.map(i => i.json);
const count = tenders.length;
const MAX_SHOWN = 10;

let lines = [`\ud83d\udd14 \u041d\u043e\u0432\u044b\u0445 \u0442\u0435\u043d\u0434\u0435\u0440\u043e\u0432: ${count}`];
for (const t of tenders.slice(0, MAX_SHOWN)) {
  const subj = (t.subject || '\u041d\u0435\u0442 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044f').slice(0, 70);
  const price = parseFloat(t.max_price || 0).toLocaleString('ru-RU', {maximumFractionDigits: 0});
  const dl = (t.collecting_end || '').slice(0, 10);
  lines.push('');
  lines.push(`\ud83d\udccb ${subj}`);
  lines.push(`\ud83d\udcb0 ${price} \u20bd | \u0420\u0435\u0433. ${t.region_code} | \u0414\u043e: ${dl}`);
  const supplierLine = t.supplier_inn
    ? `\ud83d\udc77 \u0418\u041d\u041d ${t.supplier_inn} (${t.contracts_count} \u043a\u043e\u043d\u0442., ${t.total_volume_k} \u0442\u044b\u0441. \u20bd)`
    : `\ud83d\udc77 \u041f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u043e\u0432 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e \u2014 \u043d\u0438\u0437\u043a\u0430\u044f \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u044f`;
  lines.push(supplierLine);
}
if (count > MAX_SHOWN) lines.push(`\n...\u0438 \u0435\u0449\u0451 ${count - MAX_SHOWN} \u0442\u0435\u043d\u0434\u0435\u0440\u043e\u0432`);
lines.push('');
lines.push('\ud83d\udcca \u0422\u0430\u0431\u043b\u0438\u0446\u0430: https://docs.google.com/spreadsheets/d/1FB-eK3Ts8kOe75Q085E_H3IbSTr_uinSb829SIiAiBE');

const telegram_text = lines.join('\n');

const rows = tenders.map(t => ({
  date: new Date().toISOString(),
  purchase_number: t.purchase_number,
  subject: t.subject || '',
  max_price: t.max_price,
  region_code: t.region_code,
  collecting_end: t.collecting_end || '',
  customer_inn: t.customer_inn || '',
  supplier_inn: t.supplier_inn || '',
  contracts_count: t.contracts_count,
  total_volume_k: t.total_volume_k,
  link: `https://zakupki.gov.ru/epz/order/notice/ea20/view/common-info.html?regNumber=${t.purchase_number}`
}));

return [{ json: { telegram_text, rows, count } }];

const rows = $('Code: Build Summary').first().json.rows || [];
if (rows.length === 0) return [];
return rows.map(r => ({ json: r }));
